// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// Safety-critical invariants of `LinkedList<T>`:
//
// 1. Every node reachable from `head` (following `next`) or from `tail`
//    (following `prev`) was allocated via `Box::new` and converted to a raw
//    pointer with `Box::into_raw`. Each such node is owned exclusively by the list.
// 2. `head` is `None` iff `tail` is `None` iff `len == 0`.
// 3. For every node `n`: `n.next.prev == Some(n)` (if `n.next` is `Some`) and
//    `n.prev.next == Some(n)` (if `n.prev` is `Some`). `head.prev` and `tail.next`
//    are `None`.
// 4. `len` equals the number of nodes in the list.
//
// A `Cursor` holds a `&mut LinkedList`, so while it exists no other access to the
// list is possible. Its `current` is either `None` (only when the list is empty)
// or a pointer to a node belonging to that list.
//
// An `Iter` holds a shared borrow of the list (via the lifetime 'a), so the list
// can't be mutated while the iterator exists; its `next` pointer always points to
// a node of the list or is `None`.

type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    val: T,
    prev: Link<T>,
    next: Link<T>,
}

pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    // Signals ownership of `Node<T>` values (for drop check). NonNull keeps covariance.
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    list: &'a mut LinkedList<T>,
    current: Link<T>,
}

pub struct Iter<'a, T> {
    next: Link<T>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: The list owns its `T` values exclusively (like `Box<T>`), so it can be
// sent to another thread if `T` can.
unsafe impl<T: Send> Send for LinkedList<T> {}
// SAFETY: Shared access to the list only gives shared access to `T` values.
unsafe impl<T: Sync> Sync for LinkedList<T> {}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        let current = self.head;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        let current = self.tail;
        Cursor {
            list: self,
            current,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: `current` points to a live node owned by the list (invariant 1).
        // The cursor holds the only (mutable) borrow of the list, and the returned
        // reference is tied to `&mut self`, so no aliasing can occur.
        self.current.map(|node| unsafe { &mut (*node.as_ptr()).val })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list; reading its `next` link is valid.
        let next = unsafe { (*node.as_ptr()).next };
        match next {
            Some(_) => {
                self.current = next;
                self.peek_mut()
            }
            None => None,
        }
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let node = self.current?;
        // SAFETY: `node` is a live node of the list; reading its `prev` link is valid.
        let prev = unsafe { (*node.as_ptr()).prev };
        match prev {
            Some(_) => {
                self.current = prev;
                self.peek_mut()
            }
            None => None,
        }
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let node = self.current?;
        // SAFETY: `node` was created by `Box::into_raw` and is owned by the list
        // (invariant 1). We unlink it from its neighbours (which are live nodes
        // by invariant 3) and update head/tail, so after this no pointer in the
        // list refers to it anymore; reclaiming the Box is therefore sound.
        unsafe {
            let boxed = Box::from_raw(node.as_ptr());
            match boxed.prev {
                Some(p) => (*p.as_ptr()).next = boxed.next,
                None => self.list.head = boxed.next,
            }
            match boxed.next {
                Some(n) => (*n.as_ptr()).prev = boxed.prev,
                None => self.list.tail = boxed.prev,
            }
            self.current = boxed.next.or(boxed.prev);
            self.list.len -= 1;
            Some(boxed.val)
        }
    }

    pub fn insert_after(&mut self, element: T) {
        let new = Box::new(Node {
            val: element,
            prev: self.current,
            next: None,
        });
        // SAFETY: `Box::into_raw` never returns a null pointer.
        let new = unsafe { NonNull::new_unchecked(Box::into_raw(new)) };
        match self.current {
            None => {
                // Empty list (invariant 2 and cursor invariant).
                self.list.head = Some(new);
                self.list.tail = Some(new);
                self.current = Some(new);
            }
            // SAFETY: `cur`, `new` and `cur.next` (if any) are live nodes; we
            // relink them so that invariant 3 holds afterwards.
            Some(cur) => unsafe {
                let next = (*cur.as_ptr()).next;
                (*new.as_ptr()).next = next;
                (*cur.as_ptr()).next = Some(new);
                match next {
                    Some(n) => (*n.as_ptr()).prev = Some(new),
                    None => self.list.tail = Some(new),
                }
            },
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let new = Box::new(Node {
            val: element,
            prev: None,
            next: self.current,
        });
        // SAFETY: `Box::into_raw` never returns a null pointer.
        let new = unsafe { NonNull::new_unchecked(Box::into_raw(new)) };
        match self.current {
            None => {
                // Empty list (invariant 2 and cursor invariant).
                self.list.head = Some(new);
                self.list.tail = Some(new);
                self.current = Some(new);
            }
            // SAFETY: `cur`, `new` and `cur.prev` (if any) are live nodes; we
            // relink them so that invariant 3 holds afterwards.
            Some(cur) => unsafe {
                let prev = (*cur.as_ptr()).prev;
                (*new.as_ptr()).prev = prev;
                (*cur.as_ptr()).prev = Some(new);
                match prev {
                    Some(p) => (*p.as_ptr()).next = Some(new),
                    None => self.list.head = Some(new),
                }
            },
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: `node` is a live node of a list that is immutably borrowed for
        // 'a, so it won't be mutated or freed during 'a.
        unsafe {
            let node_ref: &'a Node<T> = &*node.as_ptr();
            self.next = node_ref.next;
            Some(&node_ref.val)
        }
    }
}
```

I'll replace the placeholder implementation with a doubly linked list built on raw pointers, covering all five steps.

**Design:**
- **Nodes:** each element lives in a heap-allocated `Node<T>` with `prev` and `next` links.
- **Links:** the links are `Option<NonNull<Node<T>>>`. `NonNull` is covariant over `T`, so `LinkedList<T>` is covariant as Step 5 requires.
- **List:** `LinkedList` stores `head`, `tail` and `len`. A `PhantomData<Box<Node<T>>>` tells the compiler that the list owns `T` values, which matters for drop checking.
- **Cursor:** holds a `&mut LinkedList<T>` and a pointer to the current node. All changes to the list go through the cursor, as the exercise asks. The cursor points at nothing only when the list is empty.
- **Iter:** holds a pointer to the next node, plus a `PhantomData<&'a T>` that ties it to a shared borrow of the list.
- **Drop:** pops elements until the list is empty.
- **Send/Sync:** implemented by hand, with the same bounds as `std::collections::LinkedList`.

The invariants are documented at the top of the file, and every `unsafe` block has a comment explaining why it is safe.

