// this module adds some functionality based on the required implementations
// here like: `LinkedList::pop_back` or `Clone for LinkedList<T>`
// You are free to use anything in it, but it's mainly for the test framework.
mod pre_implemented;

use std::marker::PhantomData;
use std::ptr::NonNull;

// # Safety invariants
//
// For a `LinkedList<T>`:
// 1. Every node reachable from `head` (following `next`) was allocated via
//    `Box::new` and is exclusively owned by this list. No node is shared
//    between lists.
// 2. `head` is `None` iff `tail` is `None` iff `len == 0`.
// 3. `head.prev` is `None`, `tail.next` is `None`, and for any two
//    consecutive nodes `a`, `b`: `a.next == Some(b)` and `b.prev == Some(a)`.
// 4. `len` equals the number of nodes in the chain.
//
// For a `Cursor`:
// 5. `cur` is `None` iff the list is empty; otherwise it points to a node
//    owned by `list`. The cursor holds `&mut LinkedList`, so it has exclusive
//    access to all nodes.
//
// For an `Iter<'a, T>`:
// 6. `next` is either `None` or points to a node owned by a list that is
//    borrowed immutably for `'a`, so the node stays alive and unmodified
//    for `'a`.

type Link<T> = Option<NonNull<Node<T>>>;

struct Node<T> {
    elem: T,
    prev: Link<T>,
    next: Link<T>,
}

pub struct LinkedList<T> {
    head: Link<T>,
    tail: Link<T>,
    len: usize,
    // Signals ownership of `Node<T>` values (for drop check) while keeping
    // covariance over `T` (NonNull and Box are both covariant).
    _marker: PhantomData<Box<Node<T>>>,
}

pub struct Cursor<'a, T> {
    cur: Link<T>,
    list: &'a mut LinkedList<T>,
}

pub struct Iter<'a, T> {
    next: Link<T>,
    _marker: PhantomData<&'a T>,
}

// SAFETY: The list owns its `T` values exclusively (invariant 1), just like
// a `Vec<T>` or `Box<T>`. Sending the list sends the `T`s, which requires
// `T: Send`. Sharing `&LinkedList<T>` only gives out `&T`, which requires
// `T: Sync`.
unsafe impl<T: Send> Send for LinkedList<T> {}
unsafe impl<T: Sync> Sync for LinkedList<T> {}

// SAFETY: A cursor behaves like `&mut LinkedList<T>`.
unsafe impl<T: Send> Send for Cursor<'_, T> {}
unsafe impl<T: Sync> Sync for Cursor<'_, T> {}

// SAFETY: An iterator behaves like `&LinkedList<T>`, only handing out `&T`.
unsafe impl<T: Sync> Send for Iter<'_, T> {}
unsafe impl<T: Sync> Sync for Iter<'_, T> {}

impl<T> Default for LinkedList<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> LinkedList<T> {
    pub fn new() -> Self {
        LinkedList {
            head: None,
            tail: None,
            len: 0,
            _marker: PhantomData,
        }
    }

    // You may be wondering why it's necessary to have is_empty()
    // when it can easily be determined from len().
    // It's good custom to have both because len() can be expensive for some types,
    // whereas is_empty() is almost always cheap.
    // (Also ask yourself whether len() is expensive for LinkedList)
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }

    pub fn len(&self) -> usize {
        self.len
    }

    /// Return a cursor positioned on the front element
    pub fn cursor_front(&mut self) -> Cursor<'_, T> {
        Cursor {
            cur: self.head,
            list: self,
        }
    }

    /// Return a cursor positioned on the back element
    pub fn cursor_back(&mut self) -> Cursor<'_, T> {
        Cursor {
            cur: self.tail,
            list: self,
        }
    }

    /// Return an iterator that moves from front to back
    pub fn iter(&self) -> Iter<'_, T> {
        Iter {
            next: self.head,
            _marker: PhantomData,
        }
    }
}

impl<T> Drop for LinkedList<T> {
    fn drop(&mut self) {
        let mut cursor = self.cursor_front();
        while cursor.take().is_some() {}
    }
}

// the cursor is expected to act as if it is at the position of an element
// and it also has to work with and be able to insert into an empty list.
impl<T> Cursor<'_, T> {
    /// Take a mutable reference to the current element
    pub fn peek_mut(&mut self) -> Option<&mut T> {
        // SAFETY: By invariant 5, `cur` points to a live node owned by the
        // list, and the cursor has exclusive access to the list. The returned
        // reference borrows `self` mutably, so no other access through the
        // cursor can happen while it lives.
        self.cur.map(|node| unsafe { &mut (*node.as_ptr()).elem })
    }

    /// Move one position forward (towards the back) and
    /// return a reference to the new position
    #[allow(clippy::should_implement_trait)]
    pub fn next(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a live node (invariant 5). We only read the
        // `next` link.
        let next = unsafe { (*cur.as_ptr()).next }?;
        self.cur = Some(next);
        self.peek_mut()
    }

    /// Move one position backward (towards the front) and
    /// return a reference to the new position
    pub fn prev(&mut self) -> Option<&mut T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a live node (invariant 5). We only read the
        // `prev` link.
        let prev = unsafe { (*cur.as_ptr()).prev }?;
        self.cur = Some(prev);
        self.peek_mut()
    }

    /// Remove and return the element at the current position and move the cursor
    /// to the neighboring element that's closest to the back. This can be
    /// either the next or previous position.
    pub fn take(&mut self) -> Option<T> {
        let cur = self.cur?;
        // SAFETY: `cur` points to a node allocated via `Box` and owned by the
        // list (invariants 1 and 5), so reconstructing the Box is sound. We
        // immediately unlink it, so no dangling pointer to it remains in the
        // list. `prev` and `next`, if present, are live nodes of the same list
        // (invariant 3), and we have exclusive access through `&mut list`.
        unsafe {
            let boxed = Box::from_raw(cur.as_ptr());
            let Node { elem, prev, next } = *boxed;

            match prev {
                Some(p) => (*p.as_ptr()).next = next,
                None => self.list.head = next,
            }
            match next {
                Some(n) => (*n.as_ptr()).prev = prev,
                None => self.list.tail = prev,
            }

            self.list.len -= 1;
            self.cur = next.or(prev);
            Some(elem)
        }
    }

    /// Insert into an empty list. The cursor then points at the new node.
    fn insert_into_empty(&mut self, element: T) {
        debug_assert!(self.cur.is_none() && self.list.is_empty());
        let node = Box::new(Node {
            elem: element,
            prev: None,
            next: None,
        });
        let ptr = NonNull::from(Box::leak(node));
        self.list.head = Some(ptr);
        self.list.tail = Some(ptr);
        self.list.len = 1;
        self.cur = Some(ptr);
    }

    pub fn insert_after(&mut self, element: T) {
        let cur = match self.cur {
            None => return self.insert_into_empty(element),
            Some(cur) => cur,
        };
        // SAFETY: `cur` is a live node of the list (invariant 5), and its
        // `next`, if any, is too (invariant 3). We have exclusive access to
        // the list. The new node comes from `Box::leak`, so it is a valid,
        // uniquely owned allocation that the list now takes ownership of.
        // All links are updated so that invariant 3 holds again.
        unsafe {
            let next = (*cur.as_ptr()).next;
            let node = Box::new(Node {
                elem: element,
                prev: Some(cur),
                next,
            });
            let ptr = NonNull::from(Box::leak(node));
            (*cur.as_ptr()).next = Some(ptr);
            match next {
                Some(n) => (*n.as_ptr()).prev = Some(ptr),
                None => self.list.tail = Some(ptr),
            }
        }
        self.list.len += 1;
    }

    pub fn insert_before(&mut self, element: T) {
        let cur = match self.cur {
            None => return self.insert_into_empty(element),
            Some(cur) => cur,
        };
        // SAFETY: `cur` is a live node of the list (invariant 5), and its
        // `prev`, if any, is too (invariant 3). We have exclusive access to
        // the list. The new node comes from `Box::leak`, so it is a valid,
        // uniquely owned allocation that the list now takes ownership of.
        // All links are updated so that invariant 3 holds again.
        unsafe {
            let prev = (*cur.as_ptr()).prev;
            let node = Box::new(Node {
                elem: element,
                prev,
                next: Some(cur),
            });
            let ptr = NonNull::from(Box::leak(node));
            (*cur.as_ptr()).prev = Some(ptr);
            match prev {
                Some(p) => (*p.as_ptr()).next = Some(ptr),
                None => self.list.head = Some(ptr),
            }
        }
        self.list.len += 1;
    }
}

impl<'a, T> Iterator for Iter<'a, T> {
    type Item = &'a T;

    fn next(&mut self) -> Option<&'a T> {
        let node = self.next?;
        // SAFETY: By invariant 6, `node` is a live node of a list that is
        // immutably borrowed for `'a`. So handing out `&'a T` is sound: the
        // node won't be freed or mutated during `'a`.
        unsafe {
            let node_ref: &'a Node<T> = &*node.as_ptr();
            self.next = node_ref.next;
            Some(&node_ref.elem)
        }
    }
}
