The tests for this exercise expect a few specific behaviours, which I've built in:

- **No arguments:** every combinator resolves to `undefined` when called with no arguments.
- **Empty array:** `all`, `allSettled`, `race` and `any` resolve with `[]` when given an empty array.
- **`allSettled` results:** it resolves with an array of the resolved values or rejection reasons, kept in the original order.
- **`any` rejection:** when every promise rejects, `any` rejects with an array of the errors, kept in the original order.
- **`promisify`:** it adds a Node-style `(error, data)` callback to the original call. The returned promise rejects if `error` is set and resolves with `data` otherwise.
- **Plain values:** non-promise values in the array are wrapped with `Promise.resolve`, so they are handled too.

promises.js
```
//
// Implementation of the 'Promises' exercise.
//

export const promisify = (fn) => {
  return (...args) =>
    new Promise((resolve, reject) => {
      fn(...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
};

export const all = (promises) => {
  if (promises === undefined) {
    return Promise.resolve();
  }
  return new Promise((resolve, reject) => {
    const results = new Array(promises.length);
    let remaining = promises.length;
    if (remaining === 0) {
      resolve(results);
      return;
    }
    promises.forEach((promise, index) => {
      Promise.resolve(promise).then(
        (value) => {
          results[index] = value;
          remaining -= 1;
          if (remaining === 0) {
            resolve(results);
          }
        },
        (error) => {
          reject(error);
        },
      );
    });
  });
};

export const allSettled = (promises) => {
  if (promises === undefined) {
    return Promise.resolve();
  }
  return new Promise((resolve) => {
    const results = new Array(promises.length);
    let remaining = promises.length;
    if (remaining === 0) {
      resolve(results);
      return;
    }
    const settle = (index, outcome) => {
      results[index] = outcome;
      remaining -= 1;
      if (remaining === 0) {
        resolve(results);
      }
    };
    promises.forEach((promise, index) => {
      Promise.resolve(promise).then(
        (value) => settle(index, value),
        (error) => settle(index, error),
      );
    });
  });
};

export const race = (promises) => {
  if (promises === undefined) {
    return Promise.resolve();
  }
  return new Promise((resolve, reject) => {
    if (promises.length === 0) {
      resolve([]);
      return;
    }
    promises.forEach((promise) => {
      Promise.resolve(promise).then(resolve, reject);
    });
  });
};

export const any = (promises) => {
  if (promises === undefined) {
    return Promise.resolve();
  }
  return new Promise((resolve, reject) => {
    const errors = new Array(promises.length);
    let remaining = promises.length;
    if (remaining === 0) {
      resolve([]);
      return;
    }
    promises.forEach((promise, index) => {
      Promise.resolve(promise).then(
        (value) => {
          resolve(value);
        },
        (error) => {
          errors[index] = error;
          remaining -= 1;
          if (remaining === 0) {
            reject(errors);
          }
        },
      );
    });
  });
};
