I'll implement all five functions in `promises.js`:

- **`promisify`** wraps an error-first callback function. The returned function returns a `Promise` that rejects with `error` or resolves with `data`. It also keeps `this`, and if `fn` throws synchronously, the promise rejects.
- **`all`, `allSettled`, `race`, `any`** are built from `new Promise` and `.then` only. They don't use the built-in versions.
  - Each entry is wrapped with `Promise.resolve`, so plain values and thenables also work.
  - Handlers are attached straight away, so an input promise that has already rejected doesn't cause an unhandled-rejection warning.
  - Results and errors keep the order the promises were passed in.

Where the exercise's expected results differ from the built-ins:

- All four functions resolve with `undefined` when called with no argument.
- All four resolve with `[]` when given an empty list.
- `allSettled` resolves with the plain values and rejection reasons, not `{ status, value }` objects.
- `any` rejects with a plain array of rejection reasons, not an `AggregateError`.

promises.js
```
//
// Promises
//
// - `promisify` turns a function following the error-first callback pattern
//   into a function returning a Promise.
// - `all`, `allSettled`, `race` and `any` re-implement the built-in Promise
//   methods of the same name, without using them.
//
// As expected by this exercise:
// - every combinator resolves with `undefined` when called without argument,
//   and with `[]` when given an empty list of promises;
// - `allSettled` resolves with the plain values / rejection reasons;
// - `any` rejects with the plain list of rejection reasons.
//

/**
 * Turns a value (plain value, thenable or promise) into a promise.
 *
 * @param {*} value
 * @returns {Promise<*>}
 */
const toPromise = (value) => Promise.resolve(value);

/**
 * Turns a function following the error-first callback pattern, i.e.
 * `fn(...args, (error, data) => {})`, into a function returning a Promise
 * that rejects with `error` or resolves with `data`.
 *
 * @param {Function} fn
 * @returns {(...args: *[]) => Promise<*>}
 */
export const promisify = (fn) => {
  if (typeof fn !== 'function') {
    throw new TypeError('promisify expects a function');
  }

  return function promisified(...args) {
    return new Promise((resolve, reject) => {
      fn.call(this, ...args, (error, data) => {
        if (error) {
          reject(error);
        } else {
          resolve(data);
        }
      });
    });
  };
};

/**
 * Shared plumbing of the combinators. Returns a promise which:
 * - resolves with `undefined` when no iterable is given;
 * - resolves with `[]` when the iterable is empty;
 * - otherwise hands the entries over to `handler`, each one turned into a
 *   promise, along with the `resolve` and `reject` functions of the returned
 *   promise.
 *
 * Errors thrown synchronously (e.g. a non-iterable argument) reject the
 * returned promise instead of being thrown.
 *
 * @param {Iterable<*>|undefined} promises
 * @param {(promises: Promise<*>[], resolve: Function, reject: Function) => void} handler
 * @returns {Promise<*>}
 */
const combine = (promises, handler) =>
  new Promise((resolve, reject) => {
    if (promises === undefined) {
      resolve();
      return;
    }

    const items = [...promises].map(toPromise);

    if (items.length === 0) {
      resolve([]);
      return;
    }

    handler(items, resolve, reject);
  });

/**
 * Creates a `collect(index, value)` function storing each value at its index.
 * Once `count` values have been collected, `onComplete` is called with all of
 * them, in their original order.
 *
 * @param {number} count
 * @param {(values: *[]) => void} onComplete
 * @returns {(index: number, value: *) => void}
 */
const createCollector = (count, onComplete) => {
  const values = new Array(count);
  let pending = count;

  return (index, value) => {
    values[index] = value;
    pending -= 1;

    if (pending === 0) {
      onComplete(values);
    }
  };
};

/**
 * Resolves with the values of all the promises (in the order they were
 * given) once they have all resolved, or rejects as soon as one rejects.
 *
 * @param {Iterable<*>} [promises]
 * @returns {Promise<*[]|undefined>}
 */
export const all = (promises) =>
  combine(promises, (items, resolve, reject) => {
    const collect = createCollector(items.length, resolve);

    items.forEach((promise, index) => {
      promise.then((value) => collect(index, value), reject);
    });
  });

/**
 * Resolves once all the promises have settled, with the value or rejection
 * reason of each of them (in the order they were given).
 *
 * @param {Iterable<*>} [promises]
 * @returns {Promise<*[]|undefined>}
 */
export const allSettled = (promises) =>
  combine(promises, (items, resolve) => {
    const collect = createCollector(items.length, resolve);

    items.forEach((promise, index) => {
      const settle = (outcome) => collect(index, outcome);
      promise.then(settle, settle);
    });
  });

/**
 * Settles the same way as the first promise to settle.
 *
 * @param {Iterable<*>} [promises]
 * @returns {Promise<*>}
 */
export const race = (promises) =>
  combine(promises, (items, resolve, reject) => {
    // Only the first call to `resolve` / `reject` has an effect.
    items.forEach((promise) => {
      promise.then(resolve, reject);
    });
  });

/**
 * Resolves with the value of the first promise to resolve, or rejects with
 * the rejection reasons of all the promises (in the order they were given)
 * if they all reject.
 *
 * @param {Iterable<*>} [promises]
 * @returns {Promise<*>}
 */
export const any = (promises) =>
  combine(promises, (items, resolve, reject) => {
    const collect = createCollector(items.length, reject);

    items.forEach((promise, index) => {
      promise.then(resolve, (reason) => collect(index, reason));
    });
  });
```

