#include "perfect_numbers.h"

namespace perfect_numbers {

namespace {

// Sum of all divisors of `number` excluding `number` itself.
long long aliquot_sum(long long number) {
    if (number == 1) {
        return 0;  // 1 has no divisors other than itself
    }

    long long sum = 1;  // 1 divides every number greater than 1
    for (long long i = 2; i <= number / i; ++i) {
        if (number % i == 0) {
            sum += i;
            const long long partner = number / i;
            if (partner != i) {
                sum += partner;
            }
        }
    }
    return sum;
}

}  // namespace

classification classify(int number) {
    if (number <= 0) {
        throw std::domain_error(
            "Classification is only possible for positive integers.");
    }

    const long long n = number;
    const long long sum = aliquot_sum(n);

    if (sum == n) {
        return classification::perfect;
    }
    if (sum > n) {
        return classification::abundant;
    }
    return classification::deficient;
}

}  // namespace perfect_numbers
