  const s = String(n);
  let i = 0;
  let j = s.length - 1;
  while (i < j) {
    if (s[i] !== s[j]) return false;
    i++;
    j--;
  }
  return true;
};

const factorsOf = (value, min, max) => {
  const factors = [];
  if (value === null) return factors;
  for (let i = min; i * i <= value && i <= max; i++) {
    if (value % i === 0) {
      const j = value / i;
      if (j >= min && j <= max) factors.push([i, j]);
    }
  }
  return factors;
};

