  static generate({ minFactor = 1, maxFactor } = {}) {
    if (minFactor > maxFactor) {
      throw new Error('min must be <= max');
    }
    const min = minFactor;
    const max = maxFactor;
    let smallestCache;
    let largestCache;

    return {
      get smallest() {
        if (smallestCache === undefined) {
          let best = null;
          for (let i = min; i <= max; i++) {
            if (best !== null && i * i > best) break;
            for (let j = i; j <= max; j++) {
              const p = i * j;
              if (best !== null && p >= best) break;
              if (isPalindrome(p)) {
                best = p;
                break;
