          }
          smallestCache = { value: best, factors: factorsOf(best, min, max) };
        }
        return smallestCache;
      },
      get largest() {
        if (largestCache === undefined) {
          let best = null;
          for (let i = max; i >= min; i--) {
            if (best !== null && i * max < best) break;
            for (let j = max; j >= i; j--) {
