  let x = n;
  while (x > 0) {
    reversed = reversed * 10 + (x % 10);
    x = Math.floor(x / 10);
  }
  return reversed === n;
};

const factorsInRange = (value, min, max) => {
  const factors = [];
  if (value === null) return factors;
  const start = Math.max(min, 1);
  for (let a = start; a * a <= value && a <= max; a++) {
    if (value % a === 0) {
      const b = value / a;
      if (b >= a && b >= min && b <= max) {
        factors.push([a, b]);
      }
    }
  }
  // Handle the special case of value 0 (factor 0 within range)
  if (value === 0 && min <= 0) {
    for (let b = Math.max(min, 0); b <= max; b++) {
      factors.push([0, b]);
    }
  }
  return factors;
};

class PalindromeResult {
  constructor(min, max) {
    this.min = min;
    this.max = max;
    this._smallest = undefined;
    this._largest = undefined;
  }

