  mars: 1.8808158,
  jupiter: 11.862615,
  saturn: 29.447498,
  uranus: 84.016846,
  neptune: 164.79132,
};

export const age = (planet, seconds) => {
  const period = ORBITAL_PERIODS[String(planet).toLowerCase()];
  if (period === undefined) {
    throw new Error('not a planet');
  }
  const years = seconds / EARTH_YEAR_IN_SECONDS / period;
  return Math.round(years * 100) / 100;
};
```

The `age` function needs to take a planet name and an age in seconds. It returns the age in that planet's years, rounded to two decimal places. For example, 1,000,000,000 seconds on Earth gives 31.69. If the planet name isn't recognised, it throws a `not a planet` error.

space-age.js
```javascript
//
// This is only a SKELETON file for the 'Space Age' exercise. It's been provided as a
// convenience to get you started writing code faster.
//

const EARTH_YEAR_IN_SECONDS = 31557600;

const ORBITAL_PERIODS = {
  mercury: 0.2408467,
  venus: 0.61519726,
  earth: 1.0,
  mars: 1.8808158,
  jupiter: 11.862615,
  saturn: 29.447498,
  uranus: 84.016846,
  neptune: 164.79132,
};

export const age = (planet, seconds) => {
  const key = String(planet).toLowerCase();
  if (!Object.prototype.hasOwnProperty.call(ORBITAL_PERIODS, key)) {
    throw new Error('not a planet');
  }
  const years = seconds / EARTH_YEAR_IN_SECONDS / ORBITAL_PERIODS[key];
  return Math.round(years * 100) / 100;
};
